  "app.local": "डेटा होम ना खुलल, एह से खाली एही साइट पर एह ब्राउजर में सेव बा। अगिला बेर ई डेटा होम में चल जाई।",
  "app.vault": "एह ब्राउजर के डेटा होम में सेव बा, जवन Nivesh Sahayak के हर टूल में साझा बा। हमनी के कुछुओ ना भेजल जाला।",
  "app.help": "ई कइसे काम करेला",
  "app.helpp": "billing., cash-memo. आ credit-note. पर बनल बिल इहाँ अपने-आप लउकेला। मिलल आ दिहल पइसा इहाँ लिखीं; ऐप ओकरा के बिलन से जोड़ेला, एडवांस रखेला आ बकाया आ हाथ के कैश निकालेला।",
