  "td.catch": "एह पेमेंट से साल के कुल सीमा से ऊपर जात बा, एहसे TDS पूरा कुल पर निकालल जाई, पहिले बिना TDS के भरल {y} समेत। कुछ पर TDS पहिलहीं कट चुकल बा त खाली अंतर काटीं।",
  "td.nopan": "सही PAN ना होखे त रेट 20% भा सामान्य रेट के दोगुना में जवन ज़्यादा होखे ऊ लागेला (सामान के खरीद में 5%)। पेमेंट पावे वाला से PAN माँग लीं।",
  "td.trans": "जवन ट्रांसपोर्टर के पास 10 भा कम माल गाड़ी बा आ PAN संगे डिक्लेरेशन देवेला, ओकरा के बिना TDS के पेमेंट हो सकेला।",
  "td.q": "खाली तब काटीं जब रउआ पिछला साल के टर्नओवर ₹10 करोड़ से ऊपर रहल, आ खाली एह बिक्रेता से साल के खरीद के ₹50 लाख से ऊपर वाला हिस्सा पर।",
  "td.ib": "टैक्स ऑडिट में ना आवे वाला इंडिविजुअल के दिहल किराया पर TDS एक बेर कटेला, साल भा किरायादारी के आखिरी महीना के किराया से।",
