  "b2.jvhelp": "हर लाइन में एगो खाता आ डेबिट (Dr) भा क्रेडिट (Cr) रकम होला। पार्टी वाला लाइन से कस्टमर के बकाया भा सप्लायर के देनदारी बदलेला आ ओह लोग के स्टेटमेंट आ बकाया में देखाई देला। खर्चा आ दोसर आमदनी प्रॉफिट एंड लॉस में जाला; पूंजी, निकासी, लोन आ फिक्स्ड एसेट बैलेंस शीट में।",
