  "b2.farules": "डेप्रिसिएशन कइसे निकालल जाला",
  "b2.farule1": "खाता के डेप्रिसिएशन कंपनीज़ एक्ट, 2013 के शेड्यूल II के हिसाब से बा: हर तरह के एसेट के एगो काम के उमिर बा (जइसे कंप्यूटर 3 साल, फर्नीचर 10 साल, प्लांट आ मशीनरी 15 साल, कार 8 साल), बाचल वैल्यू आमतौर पर लागत के 5% से बेसी ना होला, आ साल के बीच में जोड़ल भा बेचल एसेट पर खाली इस्तेमाल वाला दिन के डेप्रिसिएशन लागेला। स्ट्रेट लाइन (SLM: हर साल बराबर रकम) भा रिटन डाउन वैल्यू (WDV: बाचल रकम पर तय रेट) चुनीं। प्रोपराइटर आ फर्म अक्सर इहे तरीका अपनावेलन; फैसला राउर अकाउंटेंट करेलन।",
  "b2.farule2": "इनकम टैक्स डेप्रिसिएशन हर ब्लॉक के अलग निकलेला: ब्लॉक रेट पर रिटन डाउन वैल्यू (जइसे प्लांट आ मशीनरी 15%, फर्नीचर 10%, कंप्यूटर 40%), साल में 180 दिन से कम इस्तेमाल भइल एसेट पर आधा रेट, आ बिक्री के पइसा ब्लॉक से घटेला। ई खाली इनकम टैक्स रिटर्न खातिर बा, खाता में कबो ना डालल जाला। भरल रेट आम ब्लॉक रेट हवे: अपना अकाउंटेंट से पक्का करीं, खास करके 1 अप्रैल 2026 से इनकम-टैक्स एक्ट, 2025 वाला साल खातिर।",
  "b2.farule3": "डेप्रिसिएशन राउर खाता में तबे जाला जब रउआ 'डेप्रिसिएशन डालीं' दबाईं: साल के आखिरी दिन (भा साल के बीच में आज) के जर्नल एंट्री डेप्रिसिएशन के डेबिट करेला आ हर एसेट घटावेला। बाद में एसेट बदलीं त फेर से डालीं, खाली अंतर जुड़ी।",
