  "hp.items": "हर आइटम भा सर्विस के एगो लाइन। सेव कइल आइटम चुनीं त रेट, HSN आ GST भरा जाला, भा नया लिखीं। मात्रा × रेट में से डिस्काउंट घटा के टैक्सेबल वैल्यू बनेला।",
  "hp.notes": "शर्त, बैंक डिटेल आ छपल पेज के रूप। अगिला बेर खातिर डिफॉल्ट बन के सेव होला।",
  "hp.einv": "जवना बिजनेस के ई-इनवॉइस भा ई-वे बिल बनावल जरूरी बा: फाइल डाउनलोड करीं, सरकारी पोर्टल पर अपना लॉगिन से अपलोड करीं, फेर जवाब इहाँ लोड करीं।",
  "hp.exp": "एक्सपोर्ट खातिर: शिपिंग बिल, पोर्ट आ करेंसी। एक्सपोर्ट जीरो-रेटेड बा: LUT होखे त GST ना लागे; ना होखे त IGST भर के रिफंड मिलेला।",
  "hp.s.from": "जे रउआ के पइसा दिहलस। सेव कइल कस्टमर चुनीं भा नाम लिखीं।",
  "hp.s.pay": "रकम, तारीख आ कइसे दिहल गइल। कानूनी सीमा से बेसी कैश पर चेतावनी आवेला।",
  "hp.s.to": "जेकरा के रउआ पइसा दिहनी। सेव कइल सप्लायर चुनीं भा नाम लिखीं।",
  "hp.s.lines": "पइसा कवना चीज के रहे, हर एगो के एगो लाइन (जइसे किराया, रिपेयर, भाड़ा)।",
  "hp.s.tdsrcm": "भरीं अगर एह पेमेंट से TDS कटनी, भा रिवर्स चार्ज में GST रउआ के भरे के बा।",
  "hp.s.sign": "देवे वाला, लेवे वाला आ पास करे वाला के नाम। हाथ से साइन करे के होखे त खाली छोड़ीं।",
  "hp.s.tenant": "किराया के देला आ प्रॉपर्टी के पता।",
  "hp.s.landlord": "किराया केकरा मिलेला। HRA क्लेम खातिर साल के किराया ₹1 लाख से बेसी होखे त मकान मालिक के PAN चाहीं।",
  "hp.s.rent": "महीना के किराया आ कवन-कवन महीना। हर महीना के एगो रसीद बनेला।",
  "hp.s.emp": "कर्मचारी के नाम, कोड, काम आ बैंक डिटेल।",
  "hp.s.employer": "रउआ बिजनेस के डिटेल, जइसे स्लिप पर छपेला।",
  "hp.s.att": "महीना के दिन आ जवना दिन के तनखाह बनेला। बिना पइसा के छुट्टी के तनखाह कटेला।",
  "hp.s.earn": "महीना के बेसिक, भत्ता आ बाकी पे।",
  "hp.s.ded": "PF, ESI, प्रोफेशनल टैक्स, TDS आ बाकी कटौती। बटन से ई अपने आप निकल सकेला।",
  "hp.s.entries": "हर छोट कैश खरचा भा टॉप-अप, एक-एक लाइन। चालू बैलेंस बतावेला कि डब्बा में केतना होखे के चाहीं।",
  "hp.a.home": "आज के झलक: लेवे आ देवे वाला पइसा, पुरान बकाया बिल आ नया एंट्री।",
  "hp.a.sales": "हर सेल आ हर बिल पर केतना बाकी बा। कोटेशन भा ऑर्डर के इहँवे बिल में बदलीं।",
  "hp.a.buy": "परचेज बिल, रिटर्न आ खरचा। जवन ना चुकावल गइल ऊ Dues में देखाई देला।",
  "hp.a.money": "आवे आ जाए वाला पइसा। हर पेमेंट के ओह बिल से जोड़ीं जेकर ह; बाकी सबसे पुरान बिल में जाला।",
  "hp.a.dues": "के रउआ के दी आ रउआ केकरा के देब, बिल के उमिर के हिसाब से। इहँवे से नरम WhatsApp रिमाइंडर भेजीं।",
  "hp.a.parties": "हर कस्टमर आ सप्लायर के बैलेंस। स्टेटमेंट खातिर खोलीं।",
  "hp.a.cash": "रउआ एंट्री से निकलल हाथ के कैश आ बैंक बैलेंस।",
