  "hp.a.books": "कैश बुक, बैंक बुक आ डे बुक, चालू बैलेंस के साथे।",
  "hp.m.biz": "रउआ आपन बिजनेस। डिफॉल्ट वाला नया डॉक्यूमेंट में भरेला।",
